import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;
export const durationInFrames = 1500;

const COLORS = {
  bg: "#0B1221",
  teal: "#00D4AA",
  amber: "#F59E0B",
  red: "#FF4444",
  white: "#FFFFFF",
  grey: "#94A3B8",
  darkBg: "rgba(15,25,50,0.6)",
  tealBorder: "rgba(0,212,170,0.2)",
