  { x: 30, y: 55 }, { x: 45, y: 60 }, { x: 60, y: 48 }, { x: 75, y: 55 },
  { x: 85, y: 65 }, { x: 20, y: 72 }, { x: 35, y: 78 }, { x: 50, y: 70 },
