                    radial-gradient(circle at 15% 72%, rgba(0,212,170,0.4) 0%, transparent 18%),
                    radial-gradient(circle at 68% 20%, rgba(0,212,170,0.35) 0%, transparent 18%),
                    radial-gradient(circle at 58% 68%, rgba(0,212,170,0.38) 0%, transparent 18%)
