// ─── SCENE 3 ───────────────────────────────────────────────────────────────

const COMPETITORS = [
  { name: "Joe's Coffee Shop", rating: 4.2 },
  { name: "The Daily Grind", rating: 3.8 },
  { name: "Sunrise Bakery", rating: 2.9 },
  { name: "Corner Deli", rating: 4.5 },
  { name: "Park Cafe", rating: 3.1 },
  { name: "Urban Eats", rating: 2.6 },
  { name: "Maple Street Diner", rating: 4.0 },
  { name: "The Bistro", rating: 3.3 },
];

const THRESHOLD = 3.5;

const CompetitorCard: React.FC<{
  competitor: (typeof COMPETITORS)[number];
  index: number;
  sweepFrame: number;
  currentFrame: number;
}> = ({ competitor, index, sweepFrame, currentFrame }) => {
  const { fps: f } = useVideoConfig();

  const cardProgress = spring({
    frame: currentFrame,
    fps: f,
    delay: index * 4,
    config: { damping: 200 },
  });

  const isHighRated = competitor.rating >= THRESHOLD;
  const dimOpacity = interpolate(
    currentFrame,
    [sweepFrame, sweepFrame + 20],
    [1, isHighRated ? 0.2 : 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const stars = Math.round(competitor.rating);
  const starColor = isHighRated ? COLORS.amber : COLORS.red;

  return (
    <div
      style={{
        ...containerStyle,
        width: "100%",
        height: 120,
        padding: "0 24px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        opacity: dimOpacity,
        transform: `translateX(${interpolate(cardProgress, [0, 1], [60, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })}px)`,
        boxSizing: "border-box",
        flexShrink: 0,
      }}
    >
      <div
        style={{
          fontSize: 28,
          fontWeight: "bold",
          color: COLORS.white,
          fontFamily: "'Inter', sans-serif",
        }}
      >
        {competitor.name}
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <div style={{ display: "flex", gap: 4 }}>
          {[1, 2, 3, 4, 5].map((s) => (
            <span
              key={s}
              style={{ fontSize: 24, color: s <= stars ? starColor : COLORS.grey }}
            >
              ★
            </span>
          ))}
        </div>
        <div
          style={{
            fontSize: 24,
            color: isHighRated ? COLORS.amber : COLORS.red,
            fontWeight: "bold",
            minWidth: 80,
            textAlign: "right",
            fontFamily: "'Inter', sans-serif",
          }}
        >
          {competitor.rating} ★
        </div>
      </div>
    </div>
  );
};

const Scene3: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const mapProgress = spring({ frame, fps: f, delay: 5, config: { damping: 200 } });

  // Sweep starts at frame 60, completes at 110
  const sweepY = interpolate(frame, [60, 110], [0, 100], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const tooltipProgress = spring({ frame, fps: f, delay: 130, config: { damping: 200 } });

  // Threshold label appears after sweep completes
  const thresholdLabelOpacity = interpolate(frame, [110, 125], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const CARD_HEIGHT = 120;
  const CARD_GAP = 20;
  const NUM_CARDS = COMPETITORS.length;
  const listHeight = NUM_CARDS * CARD_HEIGHT + (NUM_CARDS - 1) * CARD_GAP;

  // Extra hold: scene lingers — handled via durationInFrames in TransitionSeries
  // Threshold label fade-in
  const thresholdTranslate = interpolate(thresholdLabelOpacity, [0, 1], [12, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 80,
        }}
      >
        <div style={{ width: 2800 }}>
          <div style={{ display: "flex", gap: 40, alignItems: "flex-start" }}>
            {/* Left: Map */}
            <div
              style={{
                width: 1380,
                height: listHeight + 80,
                ...containerStyle,
                position: "relative",
                flexShrink: 0,
                opacity: interpolate(mapProgress, [0, 1], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }),
              }}
            >
              <Img
                src={staticFile("assets/other/small_dark_neighbourhood_map.png")}
                style={{ width: "100%", height: "100%", objectFit: "cover" }}
              />
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: "rgba(11,18,33,0.5)",
                }}
              />
              {MAP_PINS.map((pin, i) => {
                const pinProgress = spring({
                  frame,
                  fps: f,
                  delay: 5 + i * 2,
                  config: { damping: 200 },
                });
                const lowRatedPins = [2, 4, 5, 7];
                const isLowRated = lowRatedPins.includes(i % 8);
                const pulseDim = interpolate(
                  frame,
                  [110, 130],
                  [1, isLowRated ? 1 : 0.3],
                  { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                );
                return (
                  <div
                    key={i}
                    style={{
                      position: "absolute",
                      left: `${pin.x}%`,
                      top: `${pin.y}%`,
                      transform: "translate(-50%, -50%)",
                    }}
                  >
                    <div
                      style={{
                        width: 18,
                        height: 18,
                        borderRadius: "50%",
                        backgroundColor: isLowRated ? COLORS.red : COLORS.teal,
                        opacity: pinProgress * pulseDim,
                        boxShadow: isLowRated
                          ? `0 0 10px ${COLORS.red}`
                          : `0 0 6px ${COLORS.teal}`,
                      }}
                    />
                  </div>
                );
              })}
              <div
                style={{
                  position: "absolute",
                  left: "8%",
                  bottom: "8%",
                  width: 380,
                  background: "rgba(11,18,33,0.9)",
                  borderLeft: `3px solid ${COLORS.teal}`,
                  borderRadius: 8,
                  padding: "16px 20px",
                  opacity: tooltipProgress,
                  transform: `scale(${interpolate(tooltipProgress, [0, 1], [0.8, 1], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  })})`,
                  transformOrigin: "bottom left",
                }}
              >
                <div
                  style={{
                    fontSize: 18,
                    color: COLORS.teal,
                    fontWeight: "bold",
                    letterSpacing: 2,
                    marginBottom: 6,
                  }}
                >
                  UNDERSERVED AREA
                </div>
                <div style={{ fontSize: 16, color: COLORS.grey }}>
                  4 competitors below 3.5★
                </div>
              </div>
            </div>

            {/* Right: Cards + threshold label below */}
            <div
              style={{
                width: 1380,
                flexShrink: 0,
                display: "flex",
                flexDirection: "column",
              }}
            >
              {/* Cards list with sweep line overlay */}
              <div
                style={{
                  position: "relative",
                  display: "flex",
                  flexDirection: "column",
                  gap: CARD_GAP,
                  overflow: "visible",
                }}
              >
                {COMPETITORS.map((comp, i) => (
                  <CompetitorCard
                    key={i}
                    competitor={comp}
                    index={i}
                    sweepFrame={60}
                    currentFrame={frame}
                  />
                ))}

                {/* Amber sweep line — travels over the cards */}
                <div
                  style={{
                    position: "absolute",
                    left: 0,
                    right: 0,
                    top: `${sweepY}%`,
                    height: 3,
                    background: `linear-gradient(90deg, transparent, ${COLORS.amber}, transparent)`,
                    boxShadow: `0 0 12px ${COLORS.amber}`,
                    opacity: interpolate(frame, [60, 65], [0, 1], {
                      extrapolateLeft: "clamp",
                      extrapolateRight: "clamp",
                    }),
                    pointerEvents: "none",
                    zIndex: 10,
                  }}
                />
              </div>

              {/* Threshold label — sits BELOW all cards */}
              <div
                style={{
                  marginTop: 24,
                  textAlign: "center",
                  fontSize: 26,
                  color: COLORS.amber,
                  letterSpacing: 3,
                  fontWeight: "bold",
                  opacity: thresholdLabelOpacity,
                  transform: `translateY(${thresholdTranslate}px)`,
                  padding: "16px 0",
                  borderTop: "2px solid rgba(245,158,11,0.3)",
                }}
              >
                ── 3.5★ RATING THRESHOLD ──
              </div>
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─── SCENE 4 ───────────────────────────────────────────────────────────────

