const HighlightedText: React.FC<{ text: string }> = ({ text }) => {
  const parts: { text: string; highlight?: { color: string } }[] = [];
  let remaining = text;

  while (remaining.length > 0) {
    let earliestIdx = remaining.length;
    let foundHighlight: (typeof HIGHLIGHTS)[number] | null = null;
    let foundMatchIdx = -1;

    for (const h of HIGHLIGHTS) {
      const idx = remaining.toLowerCase().indexOf(h.word);
      if (idx !== -1 && idx < earliestIdx) {
        earliestIdx = idx;
        foundHighlight = h;
        foundMatchIdx = idx;
      }
    }

    if (foundHighlight && foundMatchIdx !== -1) {
      if (foundMatchIdx > 0) {
        parts.push({ text: remaining.slice(0, foundMatchIdx) });
      }
      parts.push({
        text: remaining.slice(foundMatchIdx, foundMatchIdx + foundHighlight.word.length),
        highlight: { color: foundHighlight.color },
      });
      remaining = remaining.slice(foundMatchIdx + foundHighlight.word.length);
    } else {
      parts.push({ text: remaining });
      break;
    }
  }

  return (
    <span>
      {parts.map((part, i) =>
        part.highlight ? (
          <span
            key={i}
            style={{
              backgroundColor:
                part.highlight.color === COLORS.red
                  ? "rgba(255,68,68,0.2)"
                  : "rgba(245,158,11,0.2)",
              color: part.highlight.color,
              borderRadius: 4,
              padding: "2px 6px",
            }}
          >
            {part.text}
          </span>
        ) : (
          <span key={i}>{part.text}</span>
        )
      )}
    </span>
  );
};

