              gap: 20,
              width: 2760,
              margin: "0 auto",
            }}
          >
            {quadrants.map((q, i) => {
              const qProgress = spring({
                frame,
                fps: f,
                delay: q.delay,
                config: { damping: 200 },
              });

              const [dx, dy] = directions[i];

              const qTranslateX = interpolate(qProgress, [0, 1], [dx, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });
              const qTranslateY = interpolate(qProgress, [0, 1], [dy, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });

              const skeletonWidths = [80, 60, 70, 50];

              return (
                <div
                  key={i}
                  style={{
                    ...containerStyle,
                    background: q.bg,
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    justifyContent: "center",
                    gap: 24,
                    opacity: qProgress,
                    transform: `translate(${qTranslateX}px, ${qTranslateY}px)`,
                  }}
                >
                  <div
                    style={{
                      width: 64,
                      height: 64,
                      borderRadius: "50%",
                      backgroundColor: "rgba(0,212,170,0.15)",
                      border: `2px solid ${COLORS.teal}`,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <span style={{ fontSize: 32, color: COLORS.teal }}>
                      {(["📍", "⭐", "🕐", "💬"] as const)[i]}
                    </span>
                  </div>
                  <div
                    style={{
                      fontSize: 36,
                      fontWeight: "bold",
                      color: COLORS.white,
                      textAlign: "center",
                    }}
                  >
                    {q.label}
                  </div>
                  <div
                    style={{
                      width: "70%",
                      display: "flex",
                      flexDirection: "column",
                      gap: 12,
                    }}
                  >
                    {skeletonWidths.map((w, li) => (
                      <div
                        key={li}
                        style={{
                          width: `${w}%`,
                          height: 12,
                          backgroundColor: "rgba(255,255,255,0.08)",
                          borderRadius: 6,
                        }}
                      />
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

